import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("plain sword for a newcomer → 100 base + 10 first insurance + 5 fee = 115 G");
    it.todo("plain amulet, staff, potion use their base premiums 60/80/40 G");
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
    it.todo("newcomer with a cursed sword (steel, enchantment 3) → premium 165 G");
    it.todo("cursed sword + plain amulet → curse surcharge only on the sword: 210 G before policy modifiers and fee");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
    it.todo("cursed sword with enchantment 5 → both surcharges apply");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("customer with exactly 2 years → loyalty discount applies");
    it.todo("second quote in the scenario gets 15 % follow-up discount");
    it.todo("long-standing customer's second contract, cursed sword enchantment 7 → premium 160 G (first insurance still applies)");
    it.todo("premium yielding a fraction (e.g. 197.5) is rounded up");
    it.todo("unknown item type in a quote → throws an error");
  });

  describe("claim", () => {
    it.todo("regular steel sword enchantment 3, damage 500 G → payout 400 G");
    it.todo("rune damage 200 G → payout 100 G");
    it.todo("steel sword enchantment 9, damage 1000 G → payout 400 G");
    it.todo("dragon-material sword enchantment 5, damage 800 G → payout 700 G");
    it.todo("dragon-material sword enchantment 9, damage 1000 G → payout 400 G");
    it.todo("dragon-material sword exactly enchantment 8, damage 1000 G → payout 400 G");
    it.todo("sword 500 G + amulet 300 G damaged → payout 600 G (deductible per damaged item)");
    it.todo("sword + amulet policy → insurance sum 1600, cap 3200 → remainingCap after claim");
    it.todo("cursed sword → cap 2000 G based on unmodified insurance value");
    it.todo("sword + 3 runes → insurance sum 1750, cap 3500");
    it.todo("two swords damaged → each entry has its own deductible, cap 4000");
    it.todo("two successive 1500 G claims on a sword → payouts 1400 then 600, remainingCap 600 then 0");
    it.todo("payout yielding a fraction (e.g. 350.5) is rounded down");
    it.todo("more damage entries of a type than insured → throws an error");
    it.todo("damage to an item not in the policy → throws an error");
    it.todo("damage with unknown item type → throws an error");
    it.todo("damage with negative amount → throws an error");
  });

  describe("CLI", () => {
    it.todo("reads scenario from stdin and writes results JSON to stdout");
    it.todo("exits non-zero and writes to stderr on an invalid scenario");
  });
});

