export type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
export type QuoteStep = { op: "quote"; items: Item[] };
export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: unknown[];
};

export type ScenarioResult = { results: unknown[] };

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 1 / 10;

const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: COMPONENT_BASE_PREMIUM,
  moonstone: COMPONENT_BASE_PREMIUM,
};

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  return counts;
};

const basePremiumForType = (type: string, count: number): number =>
  type === "rune" && count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];

export const policyBasePremium = (items: Item[]): number =>
  [...countByType(items)].reduce((sum, [type, count]) => sum + basePremiumForType(type, count), 0);

const quotePremium = (step: QuoteStep): number => {
  const policyBase = policyBasePremium(step.items);
  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE;
  return policyBase + firstInsuranceSurcharge + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const step = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: quotePremium(step) }] };
};

